test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('lineTotal works with large quantities', () => {
  assert.equal(lineTotal({ qty: 10000, unitPrice: 9500 }), 95000000);
});

test('invoiceTotals calculates subtotal and total correctly', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 10, unitPrice: 9500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 137500, discount: 0, vat: 0, total: 137500 });
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 3, unitPrice: 120000 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 360000, discount: 0, vat: 0, total: 360000 });
});

test('invoiceTotals does not mutate invoice', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 10, unitPrice: 9500 },
    ],
  };
  const before = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice), before);
});

test('invoiceTotals returns integer cents', () => {
  const invoice = {
    lines: [
      { qty: 7, unitPrice: 1001 },
      { qty: 3, unitPrice: 999 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(Number.isInteger(totals.subtotal), true);
  assert.equal(Number.isInteger(totals.total), true);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].name, 'Development (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].qty, 8);
});

