test('createInvoice calculates totals with tier discounts and VAT', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 10 * €85.00 = €850.00, with 5% gold tier discount = €42.50
  // After discount: €807.50, with 21% VAT = €169.575 ≈ €169.58
  // Total: €850.00 - €42.50 + €169.58 = €977.08
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 4250);
  assert.equal(totals.vat, 16958);
  assert.equal(totals.total, 97708);
});
